import { app, page, route, query, action, api } from "@wasp.sh/spec";
import { SignupPage } from "./src/pages/SignupPage" with { type: "ref" };
import { LoginPage } from "./src/pages/LoginPage" with { type: "ref" };
import { MainPage } from "./src/pages/MainPage" with { type: "ref" };
import { FolderPage } from "./src/pages/FolderPage" with { type: "ref" };
import { LogsPage } from "./src/pages/LogsPage" with { type: "ref" };
import { SharePage } from "./src/pages/SharePage" with { type: "ref" };

import { createFolder, createShareLink } from "./src/actions" with { type: "ref" };
import { getFolderContents, getFolderBreadcrumbs, getShareLinkInfo, getAccessLogs, getRunIdQuery } from "./src/queries" with { type: "ref" };
import { uploadFile, downloadFile, configureFileUploadMiddleware } from "./src/apis" with { type: "ref" };

export default app({
  name: "app",
  wasp: { version: "^0.25.0" },
  title: "Wasp Drive",
  head: ["<link rel='icon' href='/favicon.ico' />"],
  auth: {
    userEntity: "User",
    methods: {
      usernameAndPassword: {},
    },
    onAuthFailedRedirectTo: "/login",
  },
  spec: [
    route("SignupRoute", "/signup", page(SignupPage)),
    route("LoginRoute", "/login", page(LoginPage)),
    route("RootRoute", "/", page(MainPage, { authRequired: true })),
    route("FolderRoute", "/folder/:folderId", page(FolderPage, { authRequired: true })),
    route("LogsRoute", "/logs", page(LogsPage, { authRequired: true })),
    route("ShareRoute", "/share/:linkId", page(SharePage)),

    query(getFolderContents, { entities: ["Folder", "File"] }),
    query(getFolderBreadcrumbs, { entities: ["Folder"] }),
    query(getShareLinkInfo, { entities: ["ShareLink", "File"] }),
    query(getAccessLogs, { entities: ["AccessLog", "File"] }),
    query(getRunIdQuery, { entities: [] }),

    action(createFolder, { entities: ["Folder"] }),
    action(createShareLink, { entities: ["ShareLink", "File"] }),

    api("POST", "/api/upload", uploadFile, {
      middlewareConfigFn: configureFileUploadMiddleware,
      entities: ["File", "Folder"],
    }),
    api("GET", "/api/download/:linkId", downloadFile, {
      entities: ["File", "ShareLink", "AccessLog"],
      auth: false,
    }),
  ],
});

import { HttpError } from 'wasp/server';
import fs from 'fs';

export const getFolderContents = async (args: { folderId: number | null }, context: any) => {
  if (!context.user) {
    throw new HttpError(401, 'Unauthorized');
  }
  const userId = context.user.id;
  const folders = await context.entities.Folder.findMany({
    where: {
      userId,
      parentId: args.folderId,
    },
    orderBy: { name: 'asc' },
  });
  const files = await context.entities.File.findMany({
    where: {
      userId,
      folderId: args.folderId,
    },
    orderBy: { name: 'asc' },
  });
  return { folders, files };
};

export const getFolderBreadcrumbs = async (args: { folderId: number | null }, context: any) => {
  if (!context.user) {
    throw new HttpError(401, 'Unauthorized');
  }
  if (args.folderId === null || args.folderId === undefined) {
    return [];
  }
  const userId = context.user.id;
  const breadcrumbs = [];
  let currentFolderId: number | null = args.folderId;
  while (currentFolderId !== null) {
    const folder = await context.entities.Folder.findUnique({
      where: { id: currentFolderId, userId },
    });
    if (!folder) {
      break;
    }
    breadcrumbs.unshift(folder);
    currentFolderId = folder.parentId;
  }
  return breadcrumbs;
};

export const getShareLinkInfo = async (args: { linkId: string }, context: any) => {
  const shareLink = await context.entities.ShareLink.findUnique({
    where: { id: args.linkId },
    include: {
      file: true,
    },
  });
  if (!shareLink) {
    throw new HttpError(404, 'Share link not found');
  }
  const isPasswordProtected = !!shareLink.password;
  const isExpired = shareLink.expiresAt ? new Date() > new Date(shareLink.expiresAt) : false;

  return {
    id: shareLink.id,
    fileName: shareLink.file.name,
    fileSize: shareLink.file.size,
    isPasswordProtected,
    isExpired,
  };
};

export const getAccessLogs = async (args: any, context: any) => {
  if (!context.user) {
    throw new HttpError(401, 'Unauthorized');
  }
  const userId = context.user.id;
  const logs = await context.entities.AccessLog.findMany({
    where: {
      file: {
        userId,
      },
    },
    include: {
      file: true,
    },
    orderBy: { createdAt: 'desc' },
  });
  return logs;
};

export const getRunIdQuery = async (args: any, context: any) => {
  try {
    return fs.readFileSync('/logs/artifacts/run-id', 'utf8').trim();
  } catch (e) {
    return 'zrqdxon5np';
  }
};

import { HttpError } from 'wasp/server';
import fs from 'fs';

function getRunId(): string {
  try {
    return fs.readFileSync('/logs/artifacts/run-id', 'utf8').trim();
  } catch (e) {
    return 'zrqdxon5np';
  }
}

export const createFolder = async (args: { name: string; parentId: number | null }, context: any) => {
  if (!context.user) {
    throw new HttpError(401, 'Unauthorized');
  }
  const runId = getRunId();
  let folderName = args.name;
  if (!folderName.endsWith(`-${runId}`)) {
    folderName = `${folderName}-${runId}`;
  }

  return await context.entities.Folder.create({
    data: {
      name: folderName,
      parentId: args.parentId,
      userId: context.user.id,
    },
  });
};

export const createShareLink = async (
  args: { fileId: number; password?: string; expiresInMinutes?: number },
  context: any
) => {
  if (!context.user) {
    throw new HttpError(401, 'Unauthorized');
  }
  const userId = context.user.id;
  // Verify file belongs to user
  const file = await context.entities.File.findFirst({
    where: { id: args.fileId, userId },
  });
  if (!file) {
    throw new HttpError(404, 'File not found');
  }

  let expiresAt: Date | null = null;
  if (args.expiresInMinutes) {
    expiresAt = new Date(Date.now() + args.expiresInMinutes * 60 * 1000);
  }

  return await context.entities.ShareLink.create({
    data: {
      fileId: args.fileId,
      password: args.password || null,
      expiresAt,
    },
  });
};

import fs from 'fs';
import path from 'path';
import multer from 'multer';
import { MiddlewareConfigFn } from 'wasp/server';

// Ensure uploads directory exists
const UPLOADS_DIR = '/home/user/app/uploads/';
if (!fs.existsSync(UPLOADS_DIR)) {
  fs.mkdirSync(UPLOADS_DIR, { recursive: true });
}

const storage = multer.diskStorage({
  destination: function (req, file, cb) {
    cb(null, UPLOADS_DIR);
  },
  filename: function (req, file, cb) {
    // Avoid filename conflicts by prefixing with timestamp
    const uniqueSuffix = Date.now() + '-' + Math.round(Math.random() * 1e9);
    cb(null, uniqueSuffix + '-' + file.originalname);
  },
});

const upload = multer({ storage: storage });

export const configureFileUploadMiddleware: MiddlewareConfigFn = (config) => {
  config.set('multer', upload.single('file'));
  return config;
};

export const uploadFile = async (req: any, res: any, context: any) => {
  if (!context.user) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  if (!req.file) {
    return res.status(400).json({ error: 'No file uploaded' });
  }

  const folderId = req.body.folderId ? parseInt(req.body.folderId, 10) : null;
  const userId = context.user.id;

  // Create File metadata in database
  const fileRecord = await context.entities.File.create({
    data: {
      name: req.file.originalname,
      path: req.file.path, // Full path on disk
      mimeType: req.file.mimetype || 'application/octet-stream',
      size: req.file.size,
      folderId,
      userId,
    },
  });

  return res.json(fileRecord);
};

export const downloadFile = async (req: any, res: any, context: any) => {
  const { linkId } = req.params;
  const password = req.query.password || null;

  const shareLink = await context.entities.ShareLink.findUnique({
    where: { id: linkId },
    include: {
      file: true,
    },
  });

  if (!shareLink) {
    return res.status(404).json({ error: 'Share link not found' });
  }

  // Check expiration
  if (shareLink.expiresAt && new Date() > new Date(shareLink.expiresAt)) {
    return res.status(410).json({ error: 'Share link has expired' });
  }

  // Check password
  if (shareLink.password && shareLink.password !== password) {
    return res.status(403).json({ error: 'Incorrect password' });
  }

  const file = shareLink.file;
  if (!fs.existsSync(file.path)) {
    return res.status(404).json({ error: 'File not found on server disk' });
  }

  // Create AccessLog entry
  const ip = req.ip || req.headers['x-forwarded-for'] || 'unknown';
  const userAgent = req.headers['user-agent'] || 'unknown';

  await context.entities.AccessLog.create({
    data: {
      fileId: file.id,
      ip: String(ip),
      userAgent: String(userAgent),
    },
  });

  // Serve file
  res.setHeader('Content-Disposition', `attachment; filename="${encodeURIComponent(file.name)}"`);
  res.setHeader('Content-Type', file.mimeType);
  res.setHeader('Content-Length', file.size);

  const fileStream = fs.createReadStream(file.path);
  fileStream.pipe(res);
};

