                key={file.id}
                data-testid={`file-item-${file.id}`}
                className="file-item"
                style={{ padding: '12px 20px', backgroundColor: 'white', border: '1px solid #dee2e6', borderRadius: '6px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}
